import { motion } from 'motion/react';

export interface ProductCardData {
  id: string;
  name: string;
  category: string;
  price: number;
  image: string;
  description: string;
  featured?: boolean;
}

interface ProductCardProps {
  product: ProductCardData;
  className?: string;
}

export default function ProductCard({ product, className = '' }: ProductCardProps) {
  return (
    <motion.article
      className={`group bg-card rounded-2xl overflow-hidden cursor-pointer ${className}`}
      whileHover={{ y: -6, boxShadow: '0 20px 40px rgba(0,0,0,0.12)' }}
      transition={{ duration: 0.25, ease: 'easeOut' as const }}
    >
      <div className="aspect-square overflow-hidden bg-muted">
        <img
          src={product.image}
          alt={product.name}
          className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-105"
          loading="lazy"
        />
      </div>
      <div className="p-5">
        <span className="text-xs font-medium text-primary uppercase tracking-widest">
          {product.category}
        </span>
        <h3 className="font-heading font-semibold text-foreground mt-1 text-lg leading-snug">
          {product.name}
        </h3>
        <p className="text-foreground/60 text-sm mt-1 line-clamp-2">{product.description}</p>
        <div className="flex items-center justify-between mt-4">
          <span className="text-foreground font-semibold text-lg">${product.price}</span>
          <button className="text-xs font-medium text-primary border border-primary/30 rounded-full px-4 py-1.5 hover:bg-primary hover:text-primary-foreground transition-colors duration-200">
